import java.util.*;
public class HashThenEqualsDemo {
  public static void main(String[] args) {
    class Key { String id; Key(String id){this.id=id;} public int hashCode(){System.out.print("H");return 7;} public boolean equals(Object o){System.out.print("E");return o instanceof Key k && id.equals(k.id);} }
    var m=new java.util.HashMap<Key,Integer>(); m.put(new Key("A"),1); System.out.print("|"); m.get(new Key("A"));
  }
}
